import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def hasdig(v, d):
    while v:
        if v % 10 == d:
            return True
        v //= 10
    return False
c = 0
for idx in range(n - 1):
    if (hasdig(a[idx], 8)) and (hasdig(a[idx + 1], 8)):
        c += 1
print(c)

